input.script:
const keyboardSections = document.querySelectorAll('div');
let keyboardFound = [];
keyboardSections.forEach((d, i) => {
  if (d.textContent.includes('Keyboard') && d.textContent.includes('20 languages')) {
    keyboardFound.push({index: i, text: d.textContent.substring(0, 200), outer: d.outerHTML.substring(0, 500)});
  }
});
return keyboardFound;

// Try to find the keyboard section and check all keyboard options available on the page
const keyboardOptions = document.querySelectorAll('[data-keyboard-option], [data-autom="keyboardOption"], .rc-formoption input[type="radio"][name*="keyboard"]');
const radios = document.querySelectorAll('input[type="radio"]');
const keyboardRadios = [];
radios.forEach(r => {
  if (r.name && r.name.toLowerCase().includes('keyboard')) {
    keyboardRadios.push({name: r.name, value: r.value, disabled: r.disabled, label: r.parentElement ? r.parentElement.textContent.trim().substring(0, 50) : ''});
  }
});
return {foundRadioCount: keyboardRadios.length, options: keyboardRadios.slice(0, 30)};

// Try to find keyboard radio buttons by various selectors
const allRadios = document.querySelectorAll('input[type="radio"]');
const results = [];
allRadios.forEach(r => {
  const name = r.name || '';
  if (name.toLowerCase().includes('keyboard') || name.toLowerCase().includes('lang')) {
    results.push({name, value: r.value, id: r.id});
  }
});
// Also try to find keyboard option form
const forms = document.querySelectorAll('form');
let keyboardForms = [];
forms.forEach((f, i) => {
  if (f.textContent.includes('Keyboard') || f.name?.toLowerCase().includes('keyboard')) {
    keyboardForms.push({index: i, name: f.name, action: f.action, text: f.textContent.substring(0, 200)});
  }
});
return {radios: results, keyboardForms: keyboardForms.slice(0,5), totalRadios: allRadios.length};

// Get all radio button names and values
const allRadios = document.querySelectorAll('input[type="radio"]');
const radios = [];
allRadios.forEach(r => {
  radios.push({name: r.name, value: r.value, id: r.id, checked: r.checked, disabled: r.disabled});
});
return radios;

// Find chip radio buttons
const chipRadios = document.querySelectorAll('input[type="radio"][name="chip"]');
const results = [];
chipRadios.forEach(r => {
  results.push({name: r.name, value: r.value, id: r.id, disabled: r.disabled, checked: r.checked});
});
return {count: chipRadios.length, options: results};

// Find all radio buttons grouped by name
const allRadios = document.querySelectorAll('input[type="radio"]');
const grouped = {};
allRadios.forEach(r => {
  if (!grouped[r.name]) grouped[r.name] = [];
  grouped[r.name].push({value: r.value, id: r.id, disabled: r.disabled, checked: r.checked});
});
return Object.keys(grouped).map(name => ({name, options: grouped[name]}));

// Click the space black radio
const spaceBlackRadio = document.getElementById('_r_c_');
if (spaceBlackRadio) {
  spaceBlackRadio.click();
  return {clicked: true, checked: spaceBlackRadio.checked};
}
return {clicked: false};

// Find chip radio button
const allRadios = document.querySelectorAll('input[type="radio"]');
const results = [];
allRadios.forEach(r => {
  if (r.name && r.name.includes('chip')) {
    results.push({name: r.name, value: r.value, id: r.id, disabled: r.disabled, checked: r.checked});
  }
});
return {chipRadios: results};

// Find all elements related to chip
const all = document.querySelectorAll('*');
const chipRelated = [];
all.forEach(el => {
  const text = el.textContent || '';
  // Find labels containing chip name
  if (el.tagName === 'BUTTON' || el.tagName === 'A' || el.tagName === 'LABEL' || el.tagName === 'INPUT') {
    if (text.includes('M5') && (text.includes('chip') || text.includes('Chip'))) {
      chipRelated.push({tag: el.tagName, text: text.substring(0, 100), id: el.id, className: el.className.substring(0, 100), name: el.name});
    }
  }
});
return chipRelated.slice(0, 20);

// Find the chip selection buttons
const chipButtons = [];
const allBtns = document.querySelectorAll('button, [role="button"]');
allBtns.forEach(btn => {
  const text = btn.textContent.trim();
  if (text === 'M5 chip' || text === 'M5 Pro chip' || text === 'M5 Max chip' || text.startsWith('M5 chip') || text.startsWith('M5 Pro chip') || text.startsWith('M5 Max chip')) {
    chipButtons.push({tag: btn.tagName, text: text.substring(0, 100), id: btn.id, className: btn.className.substring(0, 100), ariaLabel: btn.getAttribute('aria-label')});
  }
});
return chipButtons;

// Find any inputs or clickable elements related to chip
const all = document.querySelectorAll('input, [data-autom*="chip"], [data-autom*="Chip"]');
const results = [];
all.forEach(el => {
  const dataAutom = el.getAttribute('data-autom') || '';
  if (dataAutom.toLowerCase().includes('chip') || (el.name && el.name.toLowerCase().includes('chip'))) {
    results.push({tag: el.tagName, name: el.name, value: el.value, id: el.id, dataAutom, disabled: el.disabled, type: el.type});
  }
});
return results;

// Check if chip radios are still disabled - if so, I need to figure out why
const m5 = document.getElementById('_r_h_');
const spaceBlack = document.getElementById('_r_c_');
return {
  spaceBlack: {checked: spaceBlack.checked, disabled: spaceBlack.disabled},
  m5: {checked: m5.checked, disabled: m5.disabled}
};

// Try to remove disabled and click the M5 radio
const m5 = document.getElementById('_r_h_');
m5.disabled = false;
m5.click();
// Also trigger change event
m5.dispatchEvent(new Event('change', {bubbles: true}));
return {clicked: true, checked: m5.checked, disabled: m5.disabled};

// Click on the label that wraps M5 chip, simulating user interaction
const m5Input = document.querySelector('input[id="_r_h_"]');
const label = document.querySelector('label[for="_r_h_"]');
if (label) {
  label.click();
}
// Also try clicking the radio
if (m5Input) {
  m5Input.click();
  m5Input.dispatchEvent(new Event('change', {bubbles: true}));
  m5Input.dispatchEvent(new Event('input', {bubbles: true}));
}
return {
  checked: m5Input?.checked,
  labelText: label?.textContent?.substring(0, 50)
};

// Get the HTML structure around the M5 chip
const m5Input = document.getElementById('_r_h_');
if (m5Input) {
  // Get parent and grandparent
  let parent = m5Input.parentElement;
  let grandparent = parent?.parentElement;
  return {
    parentTag: parent?.tagName,
    parentClass: parent?.className?.substring(0, 200),
    parentText: parent?.textContent?.substring(0, 300),
    grandparentTag: grandparent?.tagName,
    grandparentClass: grandparent?.className?.substring(0, 200)
  };
}
return null;

// Get all radio button states
const allRadios = document.querySelectorAll('input[type="radio"]');
const states = [];
allRadios.forEach(r => {
  states.push({name: r.name, value: r.value, checked: r.checked, disabled: r.disabled, id: r.id});
});
return states;

// Click the space black radio
const spaceBlackRadio = document.getElementById('_r_c_');
if (spaceBlackRadio) {
  spaceBlackRadio.click();
  return {clicked: true, checked: spaceBlackRadio.checked};
}
return {clicked: false};

// Check M5 chip radio state
const m5 = document.getElementById('_r_h_');
return {
  m5: {checked: m5?.checked, disabled: m5?.disabled}
};

// Find all radios with their details
const allRadios = document.querySelectorAll('input[type="radio"]');
const states = [];
allRadios.forEach(r => {
  states.push({name: r.name, value: r.value, checked: r.checked, disabled: r.disabled, id: r.id});
});
return states;

// Click Standard display
const standardDisplay = document.getElementById('_r_e_');
if (standardDisplay) {
  standardDisplay.click();
  return {clicked: true, checked: standardDisplay.checked};
}
return {clicked: false};

// Check all radio states
const allRadios = document.querySelectorAll('input[type="radio"]');
const states = [];
allRadios.forEach(r => {
  states.push({name: r.name, value: r.value, checked: r.checked, disabled: r.disabled, id: r.id});
});
return states;

// Click the M5 chip
const m5 = document.getElementById('_r_h_');
m5.click();
return {clicked: true, checked: m5.checked};
